const parseDate = (dateStr, isStart) => {
  if (!dateStr) return null;

  let [day, month, year] = dateStr.split('-').map(Number);

  if (!day || !month || !year) return null;

  // Create date object in UTC
  let date = new Date(Date.UTC(year, month - 1, day));

  // If it's not the start date, add one day
  if (!isStart) {
    date.setUTCDate(date.getUTCDate() + 1);
  }

  // Set time based on isStart
  date.setUTCHours(isStart ? 7 : 6, isStart ? 0 : 59, isStart ? 0 : 59, isStart ? 0 : 999);
console.log(date)
  return Math.floor(date.getTime() / 1000);
};

const dateFrom = $json.dateFrom;
const dateTo = $json.dateTo || dateFrom;

const from = parseDate(dateFrom, true);
const to = parseDate(dateTo, false);

return [{ json: { from, to } }];

const now = new Date().toISOString();
const item = $input.first().json;
let noUpdate= false;

let retryCount = 1;
let status = $('Loop Over Items').first().json.status;
let timestamp=$('Loop Over Items').first().json.timestamp
let emailSent ="NO";
let createdAt = now;


if (item && item.retryCount) {
  if ( $input.first().json.status== 'COMPLETE' || $input.first().json.status == 'RETRYFAILED'){
    noUpdate=true;
    return [
  {
    json: {
      id: item.id,  // or previous node name
      retryCount: item.retryCount,
      status,
      createdAt: item.createdAt,
      updatedAt: item.updatedAt,
      noUpdate: noUpdate
    }
  }
];
  }
  const currentRetry = parseInt(item.retryCount);
  timestamp=item.timestamp;
  emailSent=item.emailSent
  retryCount = currentRetry + 1;
  status = retryCount > 3 ? "RETRYFAILED" : item.status || "none";
  createdAt = item.createdAt;

}

return [
  {
    json: {
      id: $('Loop Over Items').first().json.id,  // or previous node name
      retryCount: retryCount.toString(),
      status,
      createdAt,
      updatedAt: now,
      noUpdate,
      timestamp,
      emailSent
    }
  }
];

function generateUUID() {
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function(c) {
    const r = Math.random() * 16 | 0;
    const v = c === 'x' ? r : (r & 0x3 | 0x8);
    return v.toString(16);
  });
}



return [{
  json: {
    uuid: generateUUID()
  }
}];

